CREATE OR REPLACE FUNCTION public.get_occupied_times(_date date) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(a.time),'{}') FROM public.appointments a WHERE a.date=_date AND a.status='active' AND a.business_id='00000000-0000-0000-0000-000000000001' $$;
CREATE OR REPLACE FUNCTION public.tenant_occupied(_business uuid,_professional uuid,_date date) RETURNS TABLE("time" text,duration integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.time,coalesce(s.duration_minutes,60) FROM public.appointments a LEFT JOIN public.services s ON s.business_id=a.business_id AND s.name=a.service WHERE a.business_id=_business AND a.professional_id=_professional AND a.date=_date AND a.status='active' $$;
GRANT EXECUTE ON FUNCTION public.tenant_occupied(uuid,uuid,date) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.validate_tenant_appointment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg public.tenant_settings; dur integer; b public.businesses; BEGIN
IF new.status<>'active' THEN RETURN new; END IF;
IF new.business_id='00000000-0000-0000-0000-000000000001' THEN RETURN new; END IF;
SELECT * INTO b FROM public.businesses WHERE id=new.business_id FOR UPDATE;
IF b.subscription_status='trial' AND b.trial_ends_at<=now() THEN RAISE EXCEPTION 'trial_expired'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.professionals WHERE id=new.professional_id AND business_id=new.business_id AND active) THEN RAISE EXCEPTION 'invalid_professional'; END IF;
SELECT duration_minutes INTO dur FROM public.services WHERE business_id=new.business_id AND name=new.service AND active LIMIT 1;
SELECT * INTO cfg FROM public.tenant_settings WHERE business_id=new.business_id;
IF dur IS NULL OR cfg.business_id IS NULL OR new.date+new.time::time<=(now() AT TIME ZONE 'America/Maceio') OR NOT extract(dow FROM new.date)::integer=ANY(cfg.open_weekdays) OR new.time::time<cfg.open_time::time OR new.time::time+make_interval(mins=>dur)>cfg.close_time::time OR mod((extract(epoch FROM (new.time::time-cfg.open_time::time))/60)::integer,cfg.slot_interval_minutes)<>0 OR EXISTS(SELECT 1 FROM public.blocked_dates WHERE business_id=new.business_id AND date=new.date) THEN RAISE EXCEPTION 'invalid_slot'; END IF;
IF cfg.lunch_start IS NOT NULL AND cfg.lunch_end IS NOT NULL AND new.time::time<cfg.lunch_end::time AND new.time::time+make_interval(mins=>dur)>cfg.lunch_start::time THEN RAISE EXCEPTION 'invalid_slot'; END IF;
IF EXISTS(SELECT 1 FROM public.appointments a LEFT JOIN public.services s ON s.business_id=a.business_id AND s.name=a.service WHERE a.business_id=new.business_id AND a.professional_id=new.professional_id AND a.date=new.date AND a.status='active' AND a.id<>new.id AND new.time::time<a.time::time+make_interval(mins=>coalesce(s.duration_minutes,60)) AND new.time::time+make_interval(mins=>dur)>a.time::time) THEN RAISE EXCEPTION 'slot_taken'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_tenant_booking BEFORE INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.validate_tenant_appointment();
CREATE OR REPLACE FUNCTION public.tenant_book(_business uuid,_professional uuid,_name text,_phone text,_service text,_date date,_time text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid; BEGIN IF length(trim(_name))<2 OR length(regexp_replace(_phone,'\D','','g'))<10 THEN RAISE EXCEPTION 'invalid'; END IF; INSERT INTO public.appointments(business_id,professional_id,client_name,phone,service,date,time) VALUES(_business,_professional,left(trim(_name),100),regexp_replace(_phone,'\D','','g'),_service,_date,_time) RETURNING id INTO i; RETURN i; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'slot_taken'; END $$;
GRANT EXECUTE ON FUNCTION public.tenant_book(uuid,uuid,text,text,text,date,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.find_my_appointment(_phone text) RETURNS TABLE(id uuid,client_name text,service text,date date,"time" text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.client_name,a.service,a.date,a.time FROM public.appointments a WHERE a.business_id='00000000-0000-0000-0000-000000000001' AND a.phone=regexp_replace(_phone,'\D','','g') AND a.status='active' AND a.date+a.time::time>(now() AT TIME ZONE 'America/Maceio') ORDER BY a.date,a.time LIMIT 1 $$;